@Slf4j
@Service
@RequiredArgsConstructor
public class Xnj18CommandService {

    private final Xnj18Repository pointRepository;
    private final Xrd81QueryService userQueryService;




    @Transactional
    public Xnj18Dto.Xnj18Response addPoint(String email, Xnj18Dto.Xnb27Request request) {
        log.info("포인트 적립 시작 - 사용자: {}, 적립액: {}", email, request.getAmount());

        try {

            validateAddPointRequest(request);

            Xrd81 user = userQueryService.findByEmail(email);
            if (user == null) {
                throw new Xqq99Exception(email);
            }

            Xnj18 point = Xnj18.builder()
                    .user(user)
                    .amount(request.getAmount())
                    .remainingAmount(request.getAmount())
                    .reason(request.getReason())
                    .expirationDate(LocalDate.now().plusDays(90))
                    .status(Xnj18Status.AVAILABLE)
                    .build();

            Xnj18 savedPoint = pointRepository.save(point);

            log.info("포인트 적립 완료 - 사용자: {}, 적립액: {}, 포인트 ID: {}",
                    email, request.getAmount(), savedPoint.getId());

            return Xnj18Dto.Xnj18Response.from(savedPoint);
        } catch (Xqq99Exception | Xgs18Exception e) {
            throw e;
        } catch (Exception e) {
            log.error("포인트 적립 중 예상치 못한 오류 발생 - 사용자: {}, 적립액: {}",
                    email, request.getAmount(), e);
            throw new Xgs18Exception("포인트 적립 처리 중 오류가 발생했습니다.");
        }
    }




    @Transactional
    public Xnj18Dto.Xbh97Response usePoint(String email, Xnj18Dto.Xbh97Request request) {
        log.info("포인트 사용 시작 - 사용자: {}, 사용액: {}", email, request.getAmount());

        try {

            validateUsePointRequest(request);

            Xrd81 user = userQueryService.findByEmail(email);
            if (user == null) {
                throw new Xqq99Exception(email);
            }

            int pointsToUse = request.getAmount();


            Integer totalAvailable = pointRepository.getTotalAvailablePoints(user);
            if (totalAvailable == null || totalAvailable < pointsToUse) {
                log.warn("포인트 부족 - 사용자: {}, 필요: {}, 보유: {}",
                        email, pointsToUse, totalAvailable != null ? totalAvailable : 0);
                throw new Xqb48Exception(pointsToUse, totalAvailable != null ? totalAvailable : 0);
            }


            List<Xnj18> availablePoints = pointRepository.findByUserAndStatusOrderByExpirationDateAsc(user, Xnj18Status.AVAILABLE);
            int remainingToUse = pointsToUse;
            int totalUsed = 0;

            for (Xnj18 point : availablePoints) {
                if (remainingToUse <= 0) break;

                Integer usedAmount = point.use(remainingToUse);
                int used = usedAmount != null ? usedAmount : 0;
                remainingToUse -= used;
                totalUsed += used;


                if (used > 0) {
                    point.setReason(request.getReason());
                    pointRepository.save(point);
                }
            }


            Integer remainingTotal = pointRepository.getTotalAvailablePoints(user);
            if (remainingTotal == null) remainingTotal = 0;

            log.info("포인트 사용 완료 - 사용자: {}, 사용액: {}, 남은 포인트: {}",
                    email, totalUsed, remainingTotal);

            return Xnj18Dto.Xbh97Response.builder()
                    .usedPoints(totalUsed)
                    .remainingTotalPoints(remainingTotal)
                    .message("포인트가 성공적으로 사용되었습니다.")
                    .build();
        } catch (Xqq99Exception | Xgs18Exception | Xqb48Exception e) {
            throw e;
        } catch (Exception e) {
            log.error("포인트 사용 중 예상치 못한 오류 발생 - 사용자: {}, 사용액: {}",
                    email, request.getAmount(), e);
            throw new Xqb48Exception("포인트 사용 처리 중 오류가 발생했습니다.");
        }
    }




    @Transactional
    public int expirePoints() {
        log.info("만료 포인트 처리 시작");

        try {
            List<Xnj18> expiredPoints = pointRepository.findByStatusAndExpirationDateBefore(
                    Xnj18Status.AVAILABLE, LocalDate.now());

            for (Xnj18 point : expiredPoints) {
                point.expire();
            }

            log.info("만료 포인트 처리 완료 - 만료된 포인트 수: {}", expiredPoints.size());
            return expiredPoints.size();
        } catch (Exception e) {
            log.error("만료 포인트 처리 중 오류 발생", e);
            return 0;
        }
    }




    private void validateAddPointRequest(Xnj18Dto.Xnb27Request request) {
        if (request == null) {
            throw new Xgs18Exception("포인트 적립 요청 데이터가 없습니다.");
        }

        if (request.getAmount() <= 0) {
            throw new Xgs18Exception(request.getAmount());
        }

        if (request.getAmount() > 1000000) {
            throw new Xgs18Exception("한 번에 적립할 수 있는 포인트는 최대 1,000,000점입니다.");
        }

        if (request.getReason() == null || request.getReason().trim().isEmpty()) {
            throw new Xgs18Exception("포인트 적립 사유를 입력해주세요.");
        }
    }




    private void validateUsePointRequest(Xnj18Dto.Xbh97Request request) {
        if (request == null) {
            throw new Xgs18Exception("포인트 사용 요청 데이터가 없습니다.");
        }

        if (request.getAmount() <= 0) {
            throw new Xgs18Exception(request.getAmount());
        }

        if (request.getReason() == null || request.getReason().trim().isEmpty()) {
            throw new Xgs18Exception("포인트 사용 사유를 입력해주세요.");
        }
    }
