import com.fream.back.domain.m13.entity.Xnj18;
import com.fream.back.domain.m13.entity.Xnj18Status;
import com.fream.back.domain.m13.entity.Xrd81;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

import java.time.LocalDate;
import java.util.List;

public interface Xnj18Repository extends JpaRepository<Xnj18, Long> {


    List<Xnj18> findByUserOrderByCreatedDateDesc(Xrd81 user);


    List<Xnj18> findByUserAndStatusOrderByExpirationDateAsc(Xrd81 user, Xnj18Status status);


    List<Xnj18> findByStatusAndExpirationDateBefore(Xnj18Status status, LocalDate date);


    @Query("SELECT SUM(p.remainingAmount) FROM Xnj18 p WHERE p.user = :user AND p.status = 'AVAILABLE'")
    Integer getTotalAvailablePoints(@Param("user") Xrd81 user);


    @Query("SELECT p FROM Xnj18 p WHERE p.user = :user AND p.status = 'AVAILABLE' AND p.expirationDate BETWEEN :today AND :expirationDate ORDER BY p.expirationDate ASC")
    List<Xnj18> findExpiringPoints(@Param("user") Xrd81 user, @Param("today") LocalDate today, @Param("expirationDate") LocalDate expirationDate);
